# Look for files related to ARC task handling
for root, dirs, files in os.walk('/home'):
    for f in files:
        if f.endswith('.py') and ('task' in f.lower() or 'arc' in f.lower()):
            path = os.path.join(root, f)
            try:
                with open(path) as file:
                    content = file.read()
                    if 'request_demos' in content or 'submit' in content:
                        print(f"Found in: {path}")
                        lines = content.split('\n')
                        for i, line in enumerate(lines[:100]):
                            if 'request_demos' in line.lower():
                                print(f"  {i}: {line}")
            except:
                pass

